  public var ATTESTATION: MEMAttestation? { let o = _accessor.offset(VT.ATTESTATION); return o == 0 ? nil : MEMAttestation(_accessor.bb, o: _accessor.indirect(o + _accessor.position)) }
  public static func startMEM(_ fbb: inout FlatBufferBuilder) -> UOffset { fbb.startTable(with: 5) }
  public static func addVectorOf(ERROR_MODELS: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ERROR_MODELS, at: VT.ERROR_MODELS) }
  public static func addVectorOf(EDITING_LEDGER: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: EDITING_LEDGER, at: VT.EDITING_LEDGER) }
  public static func add(RANDOM_SEED: UInt64, _ fbb: inout FlatBufferBuilder) { fbb.add(element: RANDOM_SEED, def: 0, at: VT.RANDOM_SEED) }
  public static func add(TRACE_ID: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: TRACE_ID, at: VT.TRACE_ID) }
  public static func add(ATTESTATION: Offset, _ fbb: inout FlatBufferBuilder) { fbb.add(offset: ATTESTATION, at: VT.ATTESTATION) }
