  public static func createMEM(
    _ fbb: inout FlatBufferBuilder,
    ERROR_MODELSVectorOffset ERROR_MODELS: Offset = Offset(),
    EDITING_LEDGERVectorOffset EDITING_LEDGER: Offset = Offset(),
    RANDOM_SEED: UInt64 = 0,
    TRACE_IDOffset TRACE_ID: Offset = Offset(),
    ATTESTATIONOffset ATTESTATION: Offset = Offset()
