    MEM.addVectorOf(EDITING_LEDGER: EDITING_LEDGER, &fbb)
    MEM.add(RANDOM_SEED: RANDOM_SEED, &fbb)
    MEM.add(TRACE_ID: TRACE_ID, &fbb)
    MEM.add(ATTESTATION: ATTESTATION, &fbb)
